reminderRowMarkup=function(row){var canManage=appointmentCapability("manage_reminders"),canSend=appointmentCapability("send_reminders"),id=String(row.id||""),status=String(row.status||"scheduled"),scheduled=status==="scheduled"||status==="programmed",actions=[];if(scheduled)actions.push('<button type="button" data-id="'+attr(id)+'" onclick="appointmentReminderAction(this.dataset.id,\'pause\')" '+(canManage?'':'disabled')+'>Pausar</button>');if(status==="paused")actions.push('<button type="button" data-id="'+attr(id)+'" onclick="appointmentReminderAction(this.dataset.id,\'resume\')" '+(canManage?'':'disabled')+'>Reanudar</button>');if((status==="failed"||status==="no_response")&&canSend)actions.push('<button type="button" data-id="'+attr(id)+'" onclick="appointmentReminderAction(this.dataset.id,\'retry\')">Reintentar</button>');if(scheduled&&canSend)actions.push('<button type="button" data-id="'+attr(id)+'" onclick="appointmentReminderAction(this.dataset.id,\'send_now\')">Enviar ahora</button>');if(reminderConversationId(row))actions.push('<button type="button" data-conversation="'+attr(reminderConversationId(row))+'" onclick="openAppointmentReminderConversation(this.dataset.conversation)">Escribir yo</button>');var scheduledAt=row.scheduled_for||row.scheduled_at,when=scheduledAt?new Date(scheduledAt).toLocaleString("es-CO",{timeZone:appointmentTimezone(),day:"numeric",month:"short",hour:"numeric",minute:"2-digit"}):(row.timing||row.offset||"");return '<div class="remRow"><span class="apptAvatar">'+esc(String(row.customer_name||"C").charAt(0))+'</span><span><strong>'+esc(row.customer_name||"Cliente")+'</strong><p>'+esc(when+(row.offset?' · '+row.offset:''))+'</p></span><span><span class="remStatus '+attr(status)+'">'+esc(reminderStatusLabel(status))+'</span><span class="remActions">'+actions.join("")+'</span></span></div>';};
renderAppointmentReminders=function(){if(!state.appointments)return;var reminders=state.appointments.reminders||[],metrics=state.appointments.metrics||{},reminderMetrics=state.appointments.reminder_metrics||{},upcoming=reminders.filter(function(row){return row.group==="upcoming"||["scheduled","programmed","paused","sending","retrying","failed"].includes(row.status);}),sent=reminders.filter(function(row){return !upcoming.includes(row);});["remRate","remRateCard"].forEach(function(id){text(id,(metrics.confirmation_rate||0)+"%");});["remAvoided","remAvoidedCard"].forEach(function(id){text(id,metrics.avoided_absences||0);});["remSent","remSentCard"].forEach(function(id){text(id,reminderMetrics.sent_count==null?(metrics.sent_reminders||0):reminderMetrics.sent_count);});text("remScheduled",reminderMetrics.scheduled_count==null?upcoming.length:reminderMetrics.scheduled_count);var a=document.getElementById("remUpcoming"),b=document.getElementById("remSentList");if(a)a.innerHTML=upcoming.map(reminderRowMarkup).join("")||'<div class="empty">No hay recordatorios próximos.</div>';if(b)b.innerHTML=sent.map(reminderRowMarkup).join("")||'<div class="empty">Aún no hay actividad.</div>';};
function appointmentReminderAction(id,action){if(!appointmentCapability("manage_reminders")){appointmentToast("Tu rol es de solo lectura.");return;}api("/admin/panel/appointment-reminders/"+encodeURIComponent(id)+"/action",{method:"POST",body:JSON.stringify({action:action})}).then(function(payload){if(payload.appointments)state.appointments=payload;else if(payload.reminders)state.appointments.reminders=payload.reminders;else if(payload.reminder){var i=(state.appointments.reminders||[]).findIndex(function(row){return String(row.id)===String(id);});if(i>=0)state.appointments.reminders[i]=payload.reminder;}if(payload.reminder_metrics)state.appointments.reminder_metrics=payload.reminder_metrics;appointmentToast("Recordatorio actualizado.");renderAppointmentReminders();}).catch(function(error){appointmentToast(error.body&&error.body.message||"No pudimos actualizar el recordatorio.");});}
function openAppointmentReminderConversation(conversationId){state.bot="appointments";showTab("conversations");var conversation=typeof findConversation==="function"&&findConversation(conversationId);state.selected=conversation&&typeof conversationKey==="function"?conversationKey(conversation):conversationId;if(typeof renderInbox==="function")renderInbox();}
function normalizeAppointmentSettings(settings){settings=settings&&settings.settings||settings||{};return {timezone:String(settings.timezone||"America/Bogota"),rules:(settings.rules||[]).map(function(rule,index){return {id:String(rule.id||"rule-"+(index+1)),text:String(rule.text||rule.instruction||""),active:rule.active!==false};}),exceptions:(settings.exceptions||[]).map(function(item,index){return {id:String(item.id||"exception-"+(index+1)),date:String(item.date||"").slice(0,10),mode:item.mode==="reschedule"?"reschedule":"close",note:String(item.note||"")};}),reminder_policy:settings.reminder_policy||{}};}
function loadAppointmentSettings(force){if(state.appointmentSettingsLoading||(!force&&state.appointmentSettings)){renderAppointmentSettings();return;}state.appointmentSettingsLoading=true;api("/admin/panel/appointment-settings").then(function(payload){state.appointmentSettings=normalizeAppointmentSettings(payload);state.appointmentSettingsRevision=payload.revision==null?null:payload.revision;renderAppointmentSettings();}).catch(function(error){text("apptSettingsStatus",error.body&&error.body.message||"No pudimos cargar estas reglas.");}).finally(function(){state.appointmentSettingsLoading=false;});}
function renderAppointmentSettings(){var settings=state.appointmentSettings;if(!settings)return;var rules=document.getElementById("apptRuleList"),exceptions=document.getElementById("apptExceptionList"),canEdit=appointmentCapability("manage_settings");if(rules)rules.innerHTML=settings.rules.map(function(rule){return '<div class="apptRuleRow"><input type="checkbox" '+(rule.active?'checked':'')+' data-id="'+attr(rule.id)+'" onchange="updateAppointmentRule(this.dataset.id,\'active\',this.checked)" '+(canEdit?'':'disabled')+'><input type="text" maxlength="500" value="'+attr(rule.text)+'" data-id="'+attr(rule.id)+'" onchange="updateAppointmentRule(this.dataset.id,\'text\',this.value)" '+(canEdit?'':'disabled')+'><button class="apptDanger" type="button" data-id="'+attr(rule.id)+'" onclick="removeAppointmentRule(this.dataset.id)" '+(canEdit?'':'disabled')+'>Eliminar</button></div>';}).join("")||'<div class="apptEmpty">Agrega la primera regla de tu agenda.</div>';if(exceptions)exceptions.innerHTML=settings.exceptions.map(function(item){return '<div class="apptExceptionRow"><span class="apptAvatar">'+(item.mode==="close"?'×':'↻')+'</span><span><strong>'+esc(item.date||"Sin fecha")+'</strong><p>'+esc(item.mode==="close"?'Cerrar el día':'Reprogramar citas')+(item.note?' · '+esc(item.note):'')+'</p></span><button class="apptDanger" type="button" data-id="'+attr(item.id)+'" onclick="removeAppointmentException(this.dataset.id)" '+(canEdit?'':'disabled')+'>Eliminar</button></div>';}).join("")||'<div class="apptEmpty">No hay excepciones.</div>';var save=document.getElementById("apptSettingsSave");if(save)save.disabled=!canEdit||state.appointmentSettingsSaving;}
function markAppointmentSettingsDirty(){text("apptSettingsStatus","Tienes cambios sin guardar.");renderAppointmentSettings();}
function addAppointmentRule(){if(!appointmentCapability("manage_settings"))return;var input=document.getElementById("apptNewRule"),value=String(input&&input.value||"").trim();if(!value){appointmentToast("Escribe la regla que debe seguir tu bot.");return;}state.appointmentSettings=state.appointmentSettings||normalizeAppointmentSettings({});state.appointmentSettings.rules.push({id:"rule-local-"+Date.now(),text:value,active:true});input.value="";markAppointmentSettingsDirty();}
function updateAppointmentRule(id,field,value){var rule=state.appointmentSettings&&state.appointmentSettings.rules.find(function(item){return item.id===id;});if(!rule)return;rule[field]=field==="active"?!!value:String(value||"").trim();markAppointmentSettingsDirty();}
