function saveAppointmentSettings(){if(state.appointmentSettingsSaving||!appointmentCapability("manage_settings"))return;state.appointmentSettingsSaving=true;renderAppointmentSettings();text("apptSettingsStatus","Guardando…");api("/admin/panel/appointment-settings",{method:"PUT",body:JSON.stringify({revision:state.appointmentSettingsRevision,settings:state.appointmentSettings})}).then(function(payload){state.appointmentSettings=normalizeAppointmentSettings(payload);state.appointmentSettingsRevision=payload.revision==null?state.appointmentSettingsRevision:payload.revision;if(state.appointments)state.appointments.settings=state.appointmentSettings;var affected=Array.isArray(payload.affected_appointments)?payload.affected_appointments.length:0;text("apptSettingsStatus",affected?affected+(affected===1?" cita quedó":" citas quedaron")+" marcadas para acordar una nueva fecha.":"Cambios guardados.");appointmentToast(affected?"Reglas guardadas y citas enviadas a revisión.":"Cómo agendar quedó actualizado.");if(affected){state.appointments=null;loadAppointments();}}).catch(function(error){if(error.status===409)loadAppointmentSettings(true);text("apptSettingsStatus",error.body&&error.body.message||"No pudimos guardar. Revisa e intenta de nuevo.");}).finally(function(){state.appointmentSettingsSaving=false;renderAppointmentSettings();});}
